// Visual explainers for the Cloud (AWS & Azure) roadmap. Schema: CONTRIBUTING.md → "Visuals".
'use strict';

// ===== Module 1: Cloud Fundamentals =========================================

registerDiagram({
  id: 'cloud-blast-radius',
  roadmap: 'cloud', module: 1, topic: 'Global Infrastructure: Regions, Availability Zones, Edge',
  kind: 'graph',
  title: 'Edge, region, AZ: where requests go and what each failure takes out',
  desc: 'A request enters at the nearest edge PoP, rides the provider backbone to a region and is spread across Availability Zones. Play it to see which layer absorbs an instance, AZ or region failure.',
  groups: [
    { id: 'region', label: 'Region (eu-west-1 / West Europe)', x: 2, y: 0, w: 5, h: 4.6, color: 'blue' },
    { id: 'aza', label: 'AZ a', x: 2.05, y: 1.05, w: 1.5, h: 2.3, color: 'green' },
    { id: 'azb', label: 'AZ b', x: 3.75, y: 1.05, w: 1.5, h: 2.3, color: 'green' },
    { id: 'azc', label: 'AZ c', x: 5.45, y: 1.05, w: 1.5, h: 2.3, color: 'green' },
  ],
  nodes: [
    { id: 'users', label: 'Users', sub: 'anywhere', icon: '🌍', x: 0, y: 0.1, color: 'gray', info: 'Latency to users is one of the four region-selection criteria, together with data residency, service availability and price.' },
    { id: 'edge', label: 'Edge PoP', sub: 'CDN · DNS · WAF', x: 1, y: 0.1, color: 'purple', info: 'AWS: 600+ CloudFront PoPs (also Route 53, Global Accelerator, Shield). Azure: Front Door PoPs. TLS is terminated close to the user and cached content never reaches the region.' },
    { id: 'global', label: 'Global services', sub: 'IAM, Route 53, Entra', x: 0, y: 1.8, color: 'purple', info: 'Global services are not tied to one region: IAM, Route 53, CloudFront, Entra ID, Front Door. Some have their control plane in a single region (for example us-east-1), so failover plans should rely on their data plane only.' },
    { id: 'lb', label: 'Regional LB', sub: 'zone-redundant', x: 4, y: 0.1, color: 'blue', info: 'ALB / Application Gateway v2 run nodes in every enabled AZ, so the load balancer itself survives an AZ loss.' },
    { id: 'vma', label: 'VM / pod', sub: 'zonal', x: 2.3, y: 1.2, color: 'green', info: 'EC2 instances, Azure zonal VMs and EBS volumes / managed disks live in exactly one AZ. They die with it.' },
    { id: 'vmb', label: 'VM / pod', sub: 'zonal', x: 4, y: 1.2, color: 'green' },
    { id: 'vmc', label: 'VM / pod', sub: 'zonal', x: 5.7, y: 1.2, color: 'green' },
    { id: 'diska', label: 'EBS / disk', sub: 'zonal', x: 2.3, y: 2.2, shape: 'db', color: 'teal' },
    { id: 'diskb', label: 'EBS / disk', sub: 'zonal', x: 4, y: 2.2, shape: 'db', color: 'teal' },
    { id: 'diskc', label: 'EBS / disk', sub: 'zonal', x: 5.7, y: 2.2, shape: 'db', color: 'teal' },
    { id: 'regional', label: 'Regional services', sub: 'S3 · DynamoDB · SQS', x: 3.75, y: 3.5, w: 1.5, shape: 'db', color: 'teal', info: 'Regional services replicate across AZs for you: S3, DynamoDB, SQS, zone-redundant storage (ZRS), zone-redundant Azure SQL. An AZ failure is invisible to callers.' },
    { id: 'dr', label: 'Region 2', sub: 'multi-region DR', x: 0, y: 3.5, color: 'orange', ghost: true, info: 'A second region only protects you if data is replicated there and the stack can run there. Paired Azure regions drive default GRS replication and staggered updates, but many newer regions are non-paired (zones first, DR region chosen by you). AWS has no pairs: you always choose.' },
  ],
  edges: [
    { from: 'users', to: 'edge' },
    { from: 'edge', to: 'lb', label: 'backbone' },
    { from: 'lb', to: 'vma' },
    { from: 'lb', to: 'vmb' },
    { from: 'lb', to: 'vmc' },
    { from: 'vma', to: 'diska' },
    { from: 'vmb', to: 'diskb' },
    { from: 'vmc', to: 'diskc' },
    { from: 'regional', to: 'dr', label: 'async replication', dashed: true },
  ],
  steps: [
    { caption: 'The user hits the nearest edge PoP (anycast or latency-based DNS). TLS terminates there and cacheable responses are served without touching the region at all.', flows: [{ from: 'users', to: 'edge', label: 'HTTPS' }] },
    { caption: 'Cache misses travel over the provider backbone, not the public internet, to a regional load balancer. The LB runs in every AZ, so it is not a single point of failure.', flows: [{ from: 'edge', to: 'lb', label: 'origin request' }] },
    { caption: 'The LB spreads requests across instances in three AZs. AZs are separate datacenters with independent power and cooling, a few milliseconds apart, so synchronous replication between them is practical.', flows: [{ from: 'lb', to: 'vma' }, { from: 'lb', to: 'vmb' }, { from: 'lb', to: 'vmc' }] },
    { caption: 'Instances and their disks are zonal. Regional services such as S3 and DynamoDB already replicate across AZs, which is why state belongs there rather than on local disks.', active: ['diska', 'diskb', 'diskc', 'regional'] },
    { caption: 'One instance fails: the LB health check removes it and the ASG / scale set replaces it. This is the smallest blast radius and needs nothing more than redundancy inside an AZ.', active: ['vmb'], flows: [{ from: 'lb', to: 'vma' }, { from: 'lb', to: 'vmc' }] },
    { caption: 'A whole AZ fails: the LB stops sending traffic there. Survive it by running in 3 AZs with enough headroom that 2 AZs can carry peak load. AZ names (us-east-1a) differ per account; use AZ IDs (use1-az1) to align accounts.', flows: [{ from: 'lb', to: 'vma' }, { from: 'lb', to: 'vmb' }], active: ['azc'] },
    { caption: 'A region fails: only a second region with replicated data helps, and global routing (Route 53, Front Door) must move users there. Global services such as IAM and Entra ID keep working, but avoid needing their control planes mid-incident.', flows: [{ from: 'regional', to: 'dr', label: 'replicated data' }], active: ['global', 'edge'] },
  ],
});

registerDiagram({
  id: 'cloud-shared-responsibility',
  roadmap: 'cloud', module: 1, topic: 'Shared Responsibility Model',
  kind: 'graph',
  title: 'Shared responsibility: who owns each layer in IaaS, PaaS, FaaS and SaaS',
  desc: 'Orange layers are yours, blue layers belong to the provider, teal ones are shared. The line moves up the stack as you move from IaaS to SaaS, but the top row never moves.',
  groups: [
    { id: 'iaas', label: 'IaaS: EC2 / Azure VM', x: 0, y: 0, w: 1.7, h: 5.1, color: 'gray' },
    { id: 'paas', label: 'PaaS: RDS / Azure SQL', x: 1.75, y: 0, w: 1.7, h: 5.1, color: 'gray' },
    { id: 'faas', label: 'FaaS: Lambda / Functions', x: 3.5, y: 0, w: 1.7, h: 5.1, color: 'gray' },
    { id: 'saas', label: 'SaaS: Microsoft 365', x: 5.25, y: 0, w: 1.7, h: 5.1, color: 'gray' },
  ],
  nodes: [
    { id: 'i1', label: 'Data + access', sub: 'customer', x: 0.1, y: 0.4, w: 1.5, h: 0.9, color: 'orange', info: 'Always yours in every model: data classification, encryption and key policy, IAM / Entra ID identities and permissions, and configuration such as public buckets and open security groups.' },
    { id: 'i2', label: 'App code', sub: 'customer', x: 0.1, y: 1.3, w: 1.5, h: 0.9, color: 'orange' },
    { id: 'i3', label: 'OS + runtime', sub: 'customer patches', x: 0.1, y: 2.2, w: 1.5, h: 0.9, color: 'orange', info: 'On EC2 or an Azure VM you patch the guest OS, harden it, install agents and rotate SSH keys (or better, use SSM Session Manager / Azure Bastion and no SSH at all).' },
    { id: 'i4', label: 'Network rules', sub: 'customer (SG / NSG)', x: 0.1, y: 3.1, w: 1.5, h: 0.9, color: 'orange' },
    { id: 'i5', label: 'Hypervisor + HW', sub: 'provider', x: 0.1, y: 4.0, w: 1.5, h: 0.9, color: 'blue' },
    { id: 'p1', label: 'Data + access', sub: 'customer', x: 1.85, y: 0.4, w: 1.5, h: 0.9, color: 'orange' },
    { id: 'p2', label: 'Schema + queries', sub: 'customer', x: 1.85, y: 1.3, w: 1.5, h: 0.9, color: 'orange', info: 'On RDS / Azure SQL you still own the schema, database users and grants, parameter settings, backup retention choices and whether the endpoint is public.' },
    { id: 'p3', label: 'OS + DB engine', sub: 'provider patches', x: 1.85, y: 2.2, w: 1.5, h: 0.9, color: 'blue', info: 'The provider patches the OS and the engine, but you choose the maintenance window and the major-version upgrade timing.' },
    { id: 'p4', label: 'Network rules', sub: 'shared', x: 1.85, y: 3.1, w: 1.5, h: 0.9, color: 'teal' },
    { id: 'p5', label: 'Hypervisor + HW', sub: 'provider', x: 1.85, y: 4.0, w: 1.5, h: 0.9, color: 'blue' },
    { id: 'f1', label: 'Data + access', sub: 'customer', x: 3.6, y: 0.4, w: 1.5, h: 0.9, color: 'orange' },
    { id: 'f2', label: 'Function code', sub: 'customer + deps', x: 3.6, y: 1.3, w: 1.5, h: 0.9, color: 'orange', info: 'Your code and its dependencies (vulnerable libraries are your problem), plus the execution role, which is the most common FaaS misconfiguration when it is over-permissive.' },
    { id: 'f3', label: 'OS + runtime', sub: 'provider', x: 3.6, y: 2.2, w: 1.5, h: 0.9, color: 'blue', info: 'The provider patches the OS and managed runtimes. You must still move off deprecated runtime versions before they are retired.' },
    { id: 'f4', label: 'Network rules', sub: 'mostly provider', x: 3.6, y: 3.1, w: 1.5, h: 0.9, color: 'teal' },
    { id: 'f5', label: 'Hypervisor + HW', sub: 'provider', x: 3.6, y: 4.0, w: 1.5, h: 0.9, color: 'blue' },
    { id: 's1', label: 'Data + access', sub: 'customer', x: 5.35, y: 0.4, w: 1.5, h: 0.9, color: 'orange', info: 'Even in SaaS you own who has access (MFA, Conditional Access, guest users) and what data you put in and share.' },
    { id: 's2', label: 'Application', sub: 'provider', x: 5.35, y: 1.3, w: 1.5, h: 0.9, color: 'blue' },
    { id: 's3', label: 'OS + runtime', sub: 'provider', x: 5.35, y: 2.2, w: 1.5, h: 0.9, color: 'blue' },
    { id: 's4', label: 'Network', sub: 'provider', x: 5.35, y: 3.1, w: 1.5, h: 0.9, color: 'blue' },
    { id: 's5', label: 'Hypervisor + HW', sub: 'provider', x: 5.35, y: 4.0, w: 1.5, h: 0.9, color: 'blue' },
  ],
  edges: [],
  steps: [
    { caption: 'IaaS: the provider secures facilities, hardware and the hypervisor (security OF the cloud). Everything from the guest OS up is yours: patching, hardening, agents, firewall rules.', active: ['i1', 'i2', 'i3', 'i4', 'i5'] },
    { caption: 'PaaS such as RDS or Azure SQL: the provider now patches the OS and the database engine. Network controls become shared: the provider runs the network, you decide whether the endpoint is public and what the SG / firewall allows.', active: ['p1', 'p2', 'p3', 'p4', 'p5'] },
    { caption: 'FaaS: you hand over the OS and runtime too, but you still own the function code, its dependencies and the execution role. An over-permissive Lambda role is a customer-side breach waiting to happen.', active: ['f1', 'f2', 'f3', 'f4', 'f5'] },
    { caption: 'SaaS: the provider runs the whole application. You still decide who can sign in and what data goes in.', active: ['s1', 's2', 's3', 's4', 's5'] },
    { caption: 'The top row never moves: data classification, encryption choices and key policy, identities and permissions. This is why most cloud breaches are customer misconfiguration: public buckets, leaked keys, over-broad roles.', active: ['i1', 'p1', 'f1', 's1'] },
    { caption: 'Interview probe: "who patches the DB engine on RDS?" (the provider) versus "who patches MySQL you installed on EC2?" (you). Same software, different service model, different owner.', active: ['i3', 'p3'] },
  ],
});

registerDiagram({
  id: 'cloud-org-guardrails',
  roadmap: 'cloud', module: 1, topic: 'Accounts, Subscriptions and Resource Hierarchy',
  kind: 'graph',
  title: 'AWS Organizations: OUs, accounts and how SCP guardrails inherit',
  desc: 'Accounts are grouped into OUs under the organization root. Policies attached higher up apply to everything below, and the effective ceiling is the intersection along the path. Azure management groups work the same way with Azure Policy.',
  nodes: [
    { id: 'root', label: 'Organization root', sub: 'management account · no workloads', x: 2.5, y: 0, w: 2, color: 'blue', info: 'The management account owns billing and the organization. SCPs and RCPs never apply to it, so keep it empty of workloads and lock it down: few humans, MFA, no access keys. Delegate security tooling to a separate audit account.' },
    { id: 'scproot', label: 'Root SCP', sub: 'leave org · regions · trail', x: 5.2, y: 0, w: 1.5, shape: 'pill', color: 'purple', info: 'Typical org-wide denies: leaving the organization, disabling CloudTrail / GuardDuty / Config, regions outside an allow-list (exempting global services), root user actions in member accounts. Written as Deny statements on top of the default FullAWSAccess policy.' },
    { id: 'ousec', label: 'Security OU', sub: 'log archive · audit', x: 0, y: 1.6, color: 'teal' },
    { id: 'ouinfra', label: 'Infrastructure OU', sub: 'network hub · shared', x: 1.5, y: 1.6, color: 'teal' },
    { id: 'ouwork', label: 'Workloads OU', sub: 'business apps', x: 3, y: 1.6, w: 1.5, color: 'teal' },
    { id: 'ousand', label: 'Sandbox OU', sub: 'budgets · auto-nuke', x: 5.2, y: 1.6, color: 'teal', info: 'Developer experimentation with looser SCPs but hard budget limits and periodic cleanup. Never connected to production networks.' },
    { id: 'scpprod', label: 'Prod SCP', sub: 'no IAM users · IMDSv2', x: 0.7, y: 3.2, w: 1.5, shape: 'pill', color: 'purple', info: 'Prod-only guardrails, for example deny iam:CreateUser and CreateAccessKey, deny launching instances without IMDSv2, deny deleting backup vaults. Declarative policies can enforce some settings (IMDSv2, no public AMI or snapshot sharing) directly in the EC2 control plane.' },
    { id: 'ouprod', label: 'Prod OU', sub: 'strictest SCPs', x: 2.5, y: 3.2, color: 'teal' },
    { id: 'ounon', label: 'NonProd OU', sub: 'dev · staging', x: 4.2, y: 3.2, color: 'teal' },
    { id: 'azure', label: 'Azure analogue', sub: 'MG tree · Policy · RBAC', x: 5.7, y: 3.2, w: 1.3, color: 'gray', ghost: true, info: 'Tenant root group > management groups (up to 6 levels) > subscriptions > resource groups. Azure Policy (deny, modify, deployIfNotExists) and RBAC role assignments inherit downwards. Azure landing zones use Platform (identity, management, connectivity) and Landing zones (corp, online) groups.' },
    { id: 'accprod', label: 'orders-prod', sub: 'member account', x: 2.5, y: 4.8, color: 'orange' },
    { id: 'accdev', label: 'orders-dev', sub: 'member account', x: 4.2, y: 4.8, color: 'orange' },
    { id: 'eff', label: 'Effective ceiling', sub: 'root ∩ every OU ∩ account', x: 0, y: 4.8, w: 2, color: 'red', info: 'An action is available in orders-prod only if the SCPs at the root, at Workloads, at Prod and on the account all allow it. One Deny anywhere on the path wins. RCPs apply the same intersection to resources in the account.' },
    { id: 'iam', label: 'IAM role', sub: 'still needs an Allow', x: 2.5, y: 6.4, color: 'blue', info: 'SCPs never grant. Inside the ceiling, an identity or resource policy must still allow the action, and permissions boundaries and session policies can narrow it further.' },
  ],
  edges: [
    { from: 'root', to: 'scproot', label: 'attached' },
    { from: 'root', to: 'ousec' },
    { from: 'root', to: 'ouinfra' },
    { from: 'root', to: 'ouwork' },
    { from: 'root', to: 'ousand' },
    { from: 'ouwork', to: 'ouprod' },
    { from: 'ouwork', to: 'ounon' },
    { from: 'scpprod', to: 'ouprod' },
    { from: 'ouprod', to: 'accprod' },
    { from: 'ounon', to: 'accdev' },
    { from: 'accprod', to: 'iam' },
  ],
  steps: [
    { caption: 'The organization root sits on the management account, which owns billing. SCPs and RCPs do not apply to it, so it runs no workloads and very few people can sign in.', active: ['root'] },
    { caption: 'OUs group accounts by function and policy needs, not by org chart: Security (log archive, audit), Infrastructure (network hub, shared services), Workloads split into Prod and NonProd, and Sandbox.', flows: [{ from: 'root', to: 'ousec' }, { from: 'root', to: 'ouinfra' }, { from: 'root', to: 'ouwork' }, { from: 'root', to: 'ousand' }] },
    { caption: 'A root SCP denies leaving the org, disabling CloudTrail and using unapproved regions. Attached once at the root, it is inherited by every OU and account below, including accounts created next year.', flows: [{ from: 'scproot', to: 'root', label: 'root SCP' }, { from: 'root', to: 'ouwork', label: 'inherited' }] },
    { caption: 'Stricter rules attach lower down: the Prod OU adds a deny on IAM users and on instances without IMDSv2. Accounts are moved between OUs, never re-configured by hand.', flows: [{ from: 'scpprod', to: 'ouprod', label: 'prod SCP' }, { from: 'ouwork', to: 'ouprod' }, { from: 'ouprod', to: 'accprod', label: 'inherited' }] },
    { caption: 'The effective ceiling for orders-prod is the intersection of the policies at the root, Workloads, Prod and the account. A Deny at any level wins; an Allow is only useful if every level allows.', active: ['eff', 'accprod', 'root', 'ouwork', 'ouprod'] },
    { caption: 'Inside that ceiling an IAM policy must still grant the action: SCPs never grant anything. That is the classic interview check: an SCP allowing s3:* gives nobody access to S3 by itself.', flows: [{ from: 'accprod', to: 'iam', label: 'needs Allow' }] },
    { caption: 'NonProd and Sandbox get looser SCPs but budgets and cleanup. New accounts come from an account vending pipeline (Control Tower Account Factory, Landing Zone Accelerator, or Terraform) with baseline roles, logging and network already in place.', flows: [{ from: 'ouwork', to: 'ounon' }, { from: 'ounon', to: 'accdev', label: 'vended' }], active: ['ousand'] },
    { caption: 'Azure: tenant root group, management groups, subscriptions and resource groups. Azure Policy and RBAC assignments inherit the same way; subscription vending plays the role of account vending.', active: ['azure'] },
  ],
});

// ===== Module 2: Identity & Access Management ===============================

registerDiagram({
  id: 'cloud-iam-policy-evaluation',
  roadmap: 'cloud', module: 2, topic: 'Policy Evaluation Logic, Permission Boundaries and SCPs',
  kind: 'graph',
  title: 'AWS policy evaluation: how a request becomes Allow or Deny',
  desc: 'Every AWS request starts as an implicit deny. It is allowed only if it survives every gate below. Play it to walk one request through the order AWS applies.',
  nodes: [
    { id: 'req', label: 'API request', sub: 'who · action · resource', x: 1.5, y: 0, w: 1.5, shape: 'pill', color: 'gray', info: 'The request context: principal (role session), action (s3:GetObject), resource ARN, and conditions such as aws:SourceIp, aws:MultiFactorAuthPresent, aws:PrincipalTag and aws:SourceVpce.' },
    { id: 'd1', label: 'Explicit Deny?', sub: 'in any policy', x: 1.5, y: 1, w: 1.5, shape: 'diamond', color: 'red' },
    { id: 'd2', label: 'SCP / RCP', sub: 'allow?', x: 1.5, y: 2, w: 1.5, shape: 'diamond', color: 'purple', info: 'Service control policies (on principals) and resource control policies (on resources) come from AWS Organizations. They only set the maximum; they never grant. They do not apply to the management account.' },
    { id: 'd3', label: 'Resource policy', sub: 'grants it?', x: 1.5, y: 3, w: 1.5, shape: 'diamond', color: 'teal', info: 'Bucket policy, KMS key policy, SQS queue policy, role trust policy. Within one account, a grant to the principal can be enough on its own. Granting a role ARN is still limited by boundaries and session policies; granting the session ARN directly is not.' },
    { id: 'd4', label: 'Identity policy', sub: 'allows?', x: 1.5, y: 4, w: 1.5, shape: 'diamond', color: 'blue' },
    { id: 'd5', label: 'Boundary', sub: 'allows? (if set)', x: 1.5, y: 5, w: 1.5, shape: 'diamond', color: 'blue', info: 'A permissions boundary is a managed policy that caps what a user or role can ever do. Enforce it with an iam:PermissionsBoundary condition so developers can create roles but cannot escalate.' },
    { id: 'd6', label: 'Session policy', sub: 'allows? (if set)', x: 1.5, y: 6, w: 1.5, shape: 'diamond', color: 'blue', info: 'An inline policy passed in AssumeRole or GetFederationToken narrows that one session.' },
    { id: 'allow', label: 'ALLOW', sub: 'all gates passed', x: 1.5, y: 7, w: 1.5, shape: 'pill', color: 'green' },
    { id: 'allow2', label: 'ALLOW', sub: 'same-account grant', x: 0, y: 3, shape: 'pill', color: 'green' },
    { id: 'deny', label: 'Explicit DENY', sub: 'nothing overrides', x: 4.5, y: 1, w: 1.5, color: 'red' },
    { id: 'implicit', label: 'Implicit DENY', sub: 'nothing allowed it', x: 4.5, y: 4, w: 1.5, color: 'red', info: 'The default answer. An implicit deny can be fixed by adding an Allow in the right place; an explicit deny cannot be overridden by any Allow.' },
  ],
  edges: [
    { from: 'req', to: 'd1' },
    { from: 'd1', to: 'deny', label: 'yes' },
    { from: 'd1', to: 'd2', label: 'no' },
    { from: 'd2', to: 'implicit', label: 'no' },
    { from: 'd2', to: 'd3', label: 'yes' },
    { from: 'd3', to: 'allow2', label: 'yes' },
    { from: 'd3', to: 'd4', label: 'no' },
    { from: 'd4', to: 'implicit', label: 'no' },
    { from: 'd4', to: 'd5', label: 'yes' },
    { from: 'd5', to: 'implicit', label: 'no' },
    { from: 'd5', to: 'd6', label: 'yes' },
    { from: 'd6', to: 'implicit', label: 'no' },
    { from: 'd6', to: 'allow', label: 'yes' },
  ],
  steps: [
    { caption: 'AWS assembles the request context: principal, action, resource and condition keys. The starting answer is always an implicit deny.', active: ['req'] },
    { caption: 'Gate 1: an explicit Deny in any applicable policy (SCP, RCP, identity, resource, boundary or session) ends evaluation. No Allow anywhere can override it, which is why guardrails are written as Deny statements.', flows: [{ from: 'req', to: 'd1' }, { from: 'd1', to: 'deny', label: 'Deny found', color: 'red' }] },
    { caption: 'Gate 2: the organization SCPs (and RCPs for the resource) must allow the action at every level of the OU path. They never grant anything: they cap what account admins can hand out.', flows: [{ from: 'd1', to: 'd2', label: 'no Deny' }, { from: 'd2', to: 'implicit', label: 'not in SCP', color: 'red' }] },
    { caption: 'Gate 3: in the same account, a resource policy naming the IAM user or role session ARN allows on its own. Naming the role ARN still passes through boundary and session policy. Cross-account, both accounts must allow.', flows: [{ from: 'd2', to: 'd3' }, { from: 'd3', to: 'allow2', label: 'granted', color: 'green' }] },
    { caption: 'Gate 4: otherwise the identity-based policies attached to the user or role must allow the action. This is the usual path for most requests.', flows: [{ from: 'd3', to: 'd4', label: 'no grant' }, { from: 'd4', to: 'implicit', label: 'not allowed', color: 'red' }] },
    { caption: 'Gate 5: if the role has a permissions boundary, the action must also be inside it. Effective permissions are the intersection of identity policy and boundary, not the union.', flows: [{ from: 'd4', to: 'd5' }, { from: 'd5', to: 'implicit', label: 'outside', color: 'red' }] },
    { caption: 'Gate 6: if a session policy was passed when assuming the role, it narrows that session further. Survive every gate and the request is allowed.', flows: [{ from: 'd5', to: 'd6' }, { from: 'd6', to: 'allow', label: 'allowed', color: 'green' }] },
    { caption: 'Contrast with Azure RBAC: it is additive (the union of role assignments at the scope and its parents) with no Deny in custom roles. Denies come only from deny assignments, and Azure Policy blocks resource configurations, not identities.', active: ['allow', 'implicit', 'deny'] },
  ],
});

registerDiagram({
  id: 'cloud-sts-assume-role',
  roadmap: 'cloud', module: 2, topic: 'STS, AssumeRole and Federation',
  kind: 'sequence',
  title: 'Cross-account AssumeRole with ExternalId',
  desc: 'A service in account A reads a bucket in account B with no long-lived keys. STS checks both sides: A must allow the call and the role trust policy in B must trust A.',
  actors: [
    { id: 'app', label: 'App role', sub: 'account A', icon: '⚙️', color: 'blue', info: 'Runs with its own role (instance profile, task role, IRSA). Its identity policy must allow sts:AssumeRole on the target role ARN.' },
    { id: 'sts', label: 'AWS STS', sub: 'token service', color: 'purple', info: 'Issues temporary credentials: access key ID, secret key, session token and expiry. Use regional STS endpoints to avoid a dependency on the global endpoint.' },
    { id: 'role', label: 'Role in B', sub: 'trust + permissions', color: 'orange', info: 'Two policies: the trust policy (who may assume it, a resource-based policy) and the permission policy (what the session may do). Trusting arn:aws:iam::A:root delegates the decision to account A admins.' },
    { id: 's3', label: 'S3 bucket', sub: 'account B', icon: '🪣', color: 'green' },
  ],
  steps: [
    { section: 'Get temporary credentials' },
    { from: 'app', to: 'sts', label: 'sts:AssumeRole', caption: 'The app calls AssumeRole with the role ARN in account B, a session name (shows up in CloudTrail) and the ExternalId it was given. It signs the call with its own current credentials.' },
    { from: 'sts', to: 'sts', label: 'A allows call?', caption: 'STS checks the caller side first: the identity policy in account A must allow sts:AssumeRole on that ARN, and no SCP in A may deny it.' },
    { from: 'sts', to: 'role', label: 'eval trust policy', caption: 'Then the resource side: the role trust policy must name the caller (account A or a specific role ARN) and its conditions must match, here sts:ExternalId. For roles, the trust policy must explicitly allow; IAM in B alone is not enough.' },
    { from: 'role', to: 'sts', label: 'trusted', reply: true, caption: 'Both sides allow the call. The session will have the role permission policy, narrowed by any session policy passed in the request.' },
    { from: 'sts', to: 'app', label: 'temp creds (1 h)', reply: true, caption: 'STS returns an access key, secret and session token. Default lifetime is 1 hour, up to the role maximum of 12 hours. Role chaining (assuming a role from a role session) caps it at 1 hour.' },
    { section: 'Use them' },
    { from: 'app', to: 's3', label: 'GetObject (SigV4, session creds)', caption: 'The app signs S3 requests with the session credentials. In CloudTrail they appear as assumed-role/RoleName/session-name, so you can trace who did what.' },
    { from: 's3', to: 's3', label: 'role perms+bucket', caption: 'S3 evaluates the role permission policy and the bucket policy. Both are in account B, so either can allow it. A KMS-encrypted bucket also needs the key policy to allow the role.' },
    { from: 's3', to: 'app', label: '200 OK', reply: true, caption: 'Data is returned. No secret was ever stored in account A config.' },
    { section: 'Confused deputy blocked' },
    { from: 'app', to: 'sts', label: 'AssumeRole (no ExtId)', caption: 'Imagine a SaaS vendor tricked by another customer into using your role ARN. Without the ExternalId you assigned to that vendor relationship, the call does not match the trust policy condition.' },
    { from: 'sts', to: 'app', label: 'AccessDenied', reply: true, caption: 'The ExternalId stops the confused deputy problem. For AWS services acting for you, aws:SourceArn and aws:SourceAccount conditions do the same job.' },
    { from: 'app', to: 'app', label: 'refresh at expiry', caption: 'The SDK credential provider re-calls AssumeRole before expiry. Azure has no AssumeRole: a principal gets an Entra ID token for an audience and Azure RBAC checks its role assignments.' },
  ],
});

registerDiagram({
  id: 'cloud-pod-workload-identity',
  roadmap: 'cloud', module: 2, topic: 'Workload Identity: Instance Roles, Managed Identities, IRSA, Pod Identity, Entra Workload ID',
  kind: 'sequence',
  title: 'Pod gets cloud credentials with no secret: IRSA, Workload ID, Pod Identity',
  desc: 'IRSA (EKS) and Microsoft Entra Workload ID (AKS) both trade a Kubernetes service account token for cloud credentials through OIDC federation. EKS Pod Identity replaces the federation with a node agent.',
  actors: [
    { id: 'node', label: 'Node', sub: 'kubelet / Pod Id agent', icon: '🖥️', color: 'gray', info: 'The kubelet projects service account tokens into pods. On EKS with Pod Identity, the eks-pod-identity-agent DaemonSet also runs here and serves credentials on a link-local address.' },
    { id: 'pod', label: 'Pod (Go SDK)', sub: 'service account sa', icon: '📦', color: 'blue', info: 'The default credential chain (AWS SDK for Go v2, azidentity.DefaultAzureCredential) finds the injected env vars and token file. No code change is needed.' },
    { id: 'sts', label: 'AWS STS / Entra ID', sub: 'token exchange', color: 'purple', info: 'AWS: AssumeRoleWithWebIdentity against a role whose trust policy names the cluster OIDC provider. Azure: Entra ID token endpoint with a federated identity credential on a user-assigned managed identity or app registration.' },
    { id: 'iss', label: 'Cluster OIDC issuer', sub: 'public discovery doc', color: 'teal', info: 'Serves /.well-known/openid-configuration and the JWKS public keys used to verify service account tokens. AWS needs an IAM OIDC identity provider registered per cluster for IRSA.' },
    { id: 'api', label: 'S3 / Blob', sub: 'cloud API', icon: '🪣', color: 'green' },
  ],
  steps: [
    { section: 'IRSA / Entra Workload ID' },
    { from: 'node', to: 'pod', label: 'projected SA token', caption: 'A mutating webhook injected env vars (AWS_ROLE_ARN + AWS_WEB_IDENTITY_TOKEN_FILE, or AZURE_CLIENT_ID + AZURE_FEDERATED_TOKEN_FILE). The kubelet writes a short-lived JWT for the service account with audience sts.amazonaws.com or api://AzureADTokenExchange.' },
    { from: 'pod', to: 'sts', label: 'exchange SA JWT', caption: 'The SDK sends the JWT: AssumeRoleWithWebIdentity on AWS, or a client_credentials request with client_assertion=JWT to Entra ID. The JWT is the only proof of identity.' },
    { from: 'sts', to: 'iss', label: 'fetch JWKS', caption: 'The token service fetches the issuer discovery document and public keys (cached). That is why the cluster issuer URL must be reachable and registered: an IAM OIDC provider on AWS, the issuer in the federated credential on Azure.' },
    { from: 'iss', to: 'sts', label: 'public keys', reply: true, caption: 'With the keys it can verify that the JWT was really signed by this cluster.' },
    { from: 'sts', to: 'sts', label: 'verify sig,sub,aud', caption: 'It checks signature, expiry, audience, and that sub equals system:serviceaccount:ns:sa as required by the role trust policy or federated credential. A wildcard sub would let any pod in the cluster in.' },
    { from: 'sts', to: 'pod', label: 'temp creds / token', reply: true, caption: 'The pod receives temporary AWS credentials or an Entra access token. The SDK refreshes both automatically before they expire.' },
    { from: 'pod', to: 'api', label: 'GetObject / read blob', caption: 'Calls are authorised by the role permission policy on AWS, or by Azure RBAC data roles (Storage Blob Data Reader) on Azure.' },
    { from: 'api', to: 'pod', label: '200 OK', reply: true, caption: 'No secret was stored in the image, the manifest or a Kubernetes Secret.' },
    { section: 'EKS Pod Identity alternative' },
    { from: 'pod', to: 'node', label: 'GET creds (agent)', caption: 'With Pod Identity the SDK asks the node agent instead. You create a Pod Identity association (cluster, namespace, service account to role) through the EKS API.' },
    { from: 'node', to: 'sts', label: 'AssumeRoleForPodIdentity', caption: 'The agent calls the EKS Auth API (drawn on the token lifeline) with the pod token. The role trusts pods.eks.amazonaws.com (sts:AssumeRole and sts:TagSession), so one role works in every cluster with no per-cluster OIDC provider.' },
    { from: 'sts', to: 'node', label: 'creds + session tags', reply: true, caption: 'Credentials come back with session tags (cluster, namespace, service account) that you can use for ABAC conditions.' },
    { from: 'node', to: 'pod', label: 'temp creds', reply: true, caption: 'The SDK uses them like any other credentials. On Azure there is no agent equivalent: Entra Workload ID is the supported path and replaces the deprecated AAD Pod Identity.' },
  ],
});

