registerDiagram({
  id: 'cloud-asg-multi-az',
  roadmap: 'cloud', module: 3, topic: 'Auto Scaling Groups and VM Scale Sets',
  kind: 'graph',
  title: 'Target tracking scale-out, health replacement and AZ loss in an ASG / VMSS',
  desc: 'An Auto Scaling group (Azure: VM Scale Set, Flexible) keeps capacity spread across three AZs behind a load balancer. Play it to watch it scale out, replace an unhealthy instance and ride out an AZ failure.',
  groups: [
    { id: 'aza', label: 'AZ a', x: 0, y: 1.55, w: 2, h: 1.4, color: 'green' },
    { id: 'azb', label: 'AZ b', x: 2, y: 1.55, w: 2, h: 1.4, color: 'green' },
    { id: 'azc', label: 'AZ c', x: 4, y: 1.55, w: 2, h: 1.4, color: 'green' },
  ],
  nodes: [
    { id: 'users', label: 'Users', icon: '👥', x: 0.5, y: 0, color: 'gray' },
    { id: 'alb', label: 'ALB', sub: 'target group', x: 2.5, y: 0, color: 'blue', info: 'Azure: Application Gateway or Standard Load Balancer with a health probe. Cross-zone load balancing is always on for ALB, so every healthy target gets a fair share.' },
    { id: 'a1', label: 'i-a1', sub: 'healthy', x: 0, y: 1.75, color: 'green' },
    { id: 'a2', label: 'i-a2', sub: 'new · warming up', x: 1, y: 1.75, color: 'green', enter: 4 },
    { id: 'b1', label: 'i-b1', sub: 'healthy', x: 2, y: 1.75, color: 'green', exit: 7, info: 'With health_check_type = ELB, the ASG replaces an instance the load balancer marks unhealthy. With only EC2 status checks, a crashed app on a running VM stays in service.' },
    { id: 'b2', label: 'i-b2', sub: 'new · warming up', x: 3, y: 1.75, color: 'green', enter: 4 },
    { id: 'c1', label: 'i-c1', sub: 'healthy', x: 4, y: 1.75, color: 'green', exit: 7 },
    { id: 'c2', label: 'i-c2', sub: 'new · warming up', x: 5, y: 1.75, color: 'green', enter: 4, exit: 7 },
    { id: 'cw', label: 'CloudWatch', sub: 'target tracking', x: 6, y: 0, color: 'purple', info: 'Target tracking creates and manages the alarms for you: keep ALBRequestCountPerTarget at 1,000 or CPU at 50%. Azure Monitor autoscale rules do the same for a scale set.' },
    { id: 'asg', label: 'Auto Scaling grp', sub: 'min 3 · max 9', x: 6, y: 1.75, color: 'orange', info: 'Desired capacity moves between min and max. It balances instances across the AZs of its subnets and supports lifecycle hooks, warm pools, instance refresh and a mixed On-Demand + Spot policy.' },
    { id: 'lt', label: 'Launch template', sub: 'AMI · IMDSv2 · role', x: 6, y: 3.3, color: 'gray', info: 'The golden image, instance types, IMDSv2-only metadata, instance profile and user data. Azure: the scale set VM profile.' },
  ],
  edges: [
    { from: 'users', to: 'alb' },
    { from: 'alb', to: 'a1' }, { from: 'alb', to: 'a2' }, { from: 'alb', to: 'b1' },
    { from: 'alb', to: 'b2' }, { from: 'alb', to: 'c1' }, { from: 'alb', to: 'c2' },
    { from: 'alb', to: 'cw', label: 'RequestCount/target' },
    { from: 'cw', to: 'asg', label: 'alarm' },
    { from: 'lt', to: 'asg' },
    { from: 'asg', to: 'c2' },
  ],
  steps: [
    { caption: 'Three instances, one per AZ, sit behind the ALB. The ALB only sends requests to targets that pass its health check.', flows: [{ from: 'users', to: 'alb' }, { from: 'alb', to: 'a1' }, { from: 'alb', to: 'b1' }, { from: 'alb', to: 'c1' }] },
    { caption: 'Traffic grows. The ALB publishes RequestCountPerTarget; it is now 1,400 against a target of 1,000. Request count suits I/O-bound Go services better than CPU.', flows: [{ from: 'alb', to: 'cw', label: '1,400 req/target' }] },
    { caption: 'Target tracking computes the capacity needed to get back to the target (3 to 6) and raises desired capacity. The launch template defines exactly what gets launched.', flows: [{ from: 'cw', to: 'asg', label: 'desired 3 → 6' }, { from: 'lt', to: 'asg', label: 'AMI, IMDSv2' }] },
    { caption: 'The ASG launches one instance per AZ to stay balanced. Each boots during the health check grace period; instance warmup keeps its metrics out of scaling decisions until it is ready. Slow boots mean bake images or use warm pools.', flows: [{ from: 'asg', to: 'c2', label: 'launch ×3' }], active: ['a2', 'b2', 'c2'] },
    { caption: 'New instances pass the ALB health check and start receiving traffic. Load per target drops back to the target value.', flows: [{ from: 'alb', to: 'a2', label: 'healthy' }, { from: 'alb', to: 'b2', label: 'healthy' }, { from: 'alb', to: 'c2', label: 'healthy' }] },
    { caption: 'i-b1 starts returning 500s on /healthz. The ALB marks it unhealthy and, because the ASG uses ELB health checks, the ASG terminates and replaces it. Keep the health endpoint shallow: if it checks the DB, one DB blip replaces the whole fleet.', flows: [{ from: 'alb', to: 'b1', label: 'HTTP 500', color: 'red' }], active: ['asg'] },
    { caption: 'Now AZ c goes dark. The ALB stops routing there within a few health check intervals and the ASG launches replacements in AZ a and b. Size min capacity so two AZs can carry peak load on their own.', flows: [{ from: 'alb', to: 'a1' }, { from: 'alb', to: 'a2' }, { from: 'alb', to: 'b2' }], active: ['azc', 'asg'] },
    { caption: 'Scale-in is conservative: the ASG deregisters a target, the ALB drains in-flight requests (deregistration delay), a lifecycle hook can finish work, then the instance terminates. Azure VMSS: autoscale profile, Application Health extension, automatic repairs.', active: ['asg', 'alb', 'a1', 'a2', 'b2'] },
  ],
});

registerDiagram({
  id: 'cloud-lambda-concurrency',
  roadmap: 'cloud', module: 3, topic: 'Serverless Functions: AWS Lambda and Azure Functions',
  kind: 'graph',
  title: 'Lambda cold starts, warm reuse, concurrency and throttling',
  desc: 'One Lambda execution environment serves one request at a time, so concurrency equals the number of environments. Play it to see a cold start, a warm reuse, a burst, a connection storm and a throttle.',
  groups: [
    { id: 'envs', label: 'Execution environments', x: 3.95, y: 0, w: 1.6, h: 3.15, color: 'orange' },
  ],
  nodes: [
    { id: 'client', label: 'Client', icon: '📱', x: 0, y: 1, color: 'gray' },
    { id: 'apigw', label: 'API Gateway', sub: 'sync invoke', x: 1.25, y: 1, color: 'blue', info: 'A synchronous trigger: the caller waits and receives a 429 if Lambda throttles. Async triggers (S3, SNS, EventBridge) queue the event and retry; poll-based triggers (SQS, Kinesis) back off.' },
    { id: 'svc', label: 'Lambda service', sub: 'placement + limits', x: 2.6, y: 1, color: 'purple', info: 'Routes each invoke to an idle warm environment or creates a new one. Enforces the regional account concurrency quota (often 1,000, but new accounts can start far lower and must request increases), reserved concurrency per function and a per-function scaling rate of 1,000 environments every 10 seconds.' },
    { id: 'env1', label: 'env 1', sub: 'cold → warm', x: 4.25, y: 0.2, color: 'orange', info: 'A Firecracker microVM. Cold start = create it, download the code, start the runtime (provided.al2023 + your bootstrap binary for Go) and run your init code. Afterwards it is frozen between invocations and reused for minutes.' },
    { id: 'env2', label: 'env 2', sub: 'cold start', x: 4.25, y: 1.15, color: 'orange', enter: 4 },
    { id: 'env3', label: 'env 3', sub: 'cold start', x: 4.25, y: 2.1, color: 'orange', enter: 4 },
    { id: 'db', label: 'RDS Proxy → DB', sub: 'pooled connections', x: 6, y: 1.15, shape: 'db', color: 'teal', info: 'Each environment holds its own connections. 1,000 environments can mean 1,000+ connections to a database sized for 200. RDS Proxy (or PgBouncer on Azure Flexible Server) multiplexes them.' },
    { id: 'throttle', label: '429 Throttled', sub: 'concurrency limit', x: 2.6, y: 2.6, color: 'red', enter: 6 },
  ],
  edges: [
    { from: 'client', to: 'apigw' },
    { from: 'apigw', to: 'svc' },
    { from: 'svc', to: 'env1' },
    { from: 'svc', to: 'env2' },
    { from: 'svc', to: 'env3' },
    { from: 'env1', to: 'db' },
    { from: 'env2', to: 'db' },
    { from: 'env3', to: 'db' },
    { from: 'svc', to: 'throttle' },
  ],
  steps: [
    { caption: 'First request, no environment exists: a cold start. Lambda creates a microVM, downloads the code and runs the init phase: everything outside the handler, such as SDK clients and config. A small static Go binary on arm64 keeps this short.', flows: [{ from: 'client', to: 'apigw' }, { from: 'apigw', to: 'svc' }, { from: 'svc', to: 'env1', label: 'INIT + invoke' }] },
    { caption: 'The handler runs and returns. The environment is frozen, not destroyed, and kept warm for later invocations. Init cost is paid once per environment, not per request.', flows: [{ from: 'env1', to: 'svc', label: 'response' }, { from: 'apigw', to: 'client', label: '200' }] },
    { caption: 'The next request finds env 1 idle and reuses it: no init, and globals such as the DB pool and SDK clients survive. That is why expensive setup belongs outside the handler.', flows: [{ from: 'svc', to: 'env1', label: 'warm invoke' }] },
    { caption: 'A burst of three concurrent requests needs three environments, because each serves one request at a time. Concurrency is roughly requests per second times duration, and every new environment pays a cold start.', flows: [{ from: 'svc', to: 'env1' }, { from: 'svc', to: 'env2', label: 'cold start' }, { from: 'svc', to: 'env3', label: 'cold start' }] },
    { caption: 'Every environment opens its own database connections. Scale out far enough and the database runs out of connections, so put RDS Proxy (or PgBouncer) in between.', flows: [{ from: 'env1', to: 'db' }, { from: 'env2', to: 'db' }, { from: 'env3', to: 'db' }] },
    { caption: 'At the concurrency limit (reserved concurrency, or the account limit shared with other functions) new sync requests get 429. Async events are retried for up to 6 hours, then sent to a DLQ or on-failure destination.', flows: [{ from: 'apigw', to: 'svc' }, { from: 'svc', to: 'throttle', label: 'over limit', color: 'red' }] },
    { caption: 'Fixes for p99 spikes: provisioned concurrency keeps N environments initialised, reserved concurrency protects critical functions, raise the account quota. Azure Functions: always-ready instances (Flex Consumption) or pre-warmed (Premium).', active: ['env1', 'env2', 'env3', 'svc'] },
  ],
});

