registerDiagram({
  id: 'cloud-global-api-two-regions',
  roadmap: 'cloud', module: 5, problem: 'Design a global, highly available API across two regions',
  kind: 'graph',
  title: 'Global API across two regions: edge routing, replication and regional failover',
  desc: 'A global edge (Front Door, CloudFront or Global Accelerator) health-probes two full regional stacks. Play it to see normal active-active routing, then a region failure.',
  groups: [
    { id: 'ra', label: 'Region A (primary writer)', x: 3, y: 0, w: 4, h: 1.8, color: 'blue' },
    { id: 'rb', label: 'Region B', x: 3, y: 3, w: 4, h: 1.8, color: 'green' },
  ],
  nodes: [
    { id: 'users', label: 'Users', icon: '🌍', x: 0, y: 2, color: 'gray' },
    { id: 'edge', label: 'Global edge + WAF', sub: 'Front Door / CloudFront', x: 1.1, y: 2, w: 1.5, color: 'purple', info: 'Anycast entry, TLS at the edge, WAF and caching, with health-probed origins in both regions. Failover takes seconds because it does not wait for DNS TTLs. Route 53 latency + failover records with health checks are the DNS-based alternative; Global Accelerator suits non-HTTP traffic.' },
    { id: 'lba', label: 'ALB / App GW', sub: 'zone-redundant', x: 3.2, y: 0.5, color: 'blue' },
    { id: 'appa', label: 'API pods', sub: 'across 3 AZs', x: 4.6, y: 0.5, color: 'blue' },
    { id: 'dba', label: 'DB writer', sub: 'single writer', x: 6, y: 0.5, shape: 'db', color: 'teal', exit: 6, info: 'Single-writer options: Aurora Global Database (typically sub-second lag), Azure SQL failover groups. Multi-writer options: DynamoDB global tables, Cosmos DB multi-region writes (last-writer-wins or custom conflict resolution).' },
    { id: 'lbb', label: 'ALB / App GW', sub: 'zone-redundant', x: 3.2, y: 3.5, color: 'green' },
    { id: 'appb', label: 'API pods', sub: 'pre-scaled', x: 4.6, y: 3.5, color: 'green' },
    { id: 'dbb', label: 'DB replica', sub: 'promotable', x: 6, y: 3.5, shape: 'db', color: 'teal' },
  ],
  edges: [
    { from: 'users', to: 'edge' },
    { from: 'edge', to: 'lba' },
    { from: 'edge', to: 'lbb' },
    { from: 'lba', to: 'appa' },
    { from: 'appa', to: 'dba' },
    { from: 'lbb', to: 'appb' },
    { from: 'appb', to: 'dbb' },
    { from: 'dba', to: 'dbb', label: 'async replication' },
  ],
  steps: [
    { caption: 'Users hit the nearest edge PoP. TLS terminates there, the WAF filters abuse, and cacheable GETs never reach a region.', flows: [{ from: 'users', to: 'edge', label: 'HTTPS' }] },
    { caption: 'The edge forwards to the closest healthy origin. Each region is a complete stack across three AZs, so an AZ failure is handled inside the region and never reaches the global layer.', flows: [{ from: 'edge', to: 'lba', label: 'latency routing' }, { from: 'lba', to: 'appa' }, { from: 'appa', to: 'dba', label: 'write' }] },
    { caption: 'Active-active for reads: users near region B are served there. Writes either go to the single writer in A, or to the local region when the database supports multi-region writes.', flows: [{ from: 'edge', to: 'lbb', label: 'nearby users' }, { from: 'lbb', to: 'appb' }, { from: 'appb', to: 'dbb', label: 'read' }] },
    { caption: 'Replication is asynchronous, so RPO equals replication lag. Synchronous cross-region writes would add tens of milliseconds to every write. Choose active-active or active-passive by how much inconsistency the business accepts.', flows: [{ from: 'dba', to: 'dbb', label: 'lag < 1 s' }] },
    { caption: 'The edge probes a health endpoint in each region every few seconds. The probe should test what matters (can this region serve requests) without failing on every minor dependency blip.', flows: [{ from: 'edge', to: 'lba', label: 'probe /health' }, { from: 'edge', to: 'lbb', label: 'probe /health' }] },
    { caption: 'Region A fails. The edge marks its origin unhealthy and sends all traffic to B within seconds. The replica is promoted (managed Aurora Global failover, or nothing to do for global tables / Cosmos multi-write). Region B was pre-scaled: static stability.', flows: [{ from: 'edge', to: 'lbb', label: 'all traffic' }, { from: 'lbb', to: 'appb' }, { from: 'appb', to: 'dbb', label: 'writes now' }], active: ['ra'] },
    { caption: 'What interviewers probe: no control-plane calls on the failover path, idempotency keys because clients retry writes, writes that landed in A but never replicated, and regular failover drills including failback.', active: ['edge', 'dbb', 'appb'] },
  ],
});

registerDiagram({
  id: 'cloud-lb-keepalive-502',
  roadmap: 'cloud', module: 5, topic: 'Health Checks, TLS Termination and Connection Behaviour',
  kind: 'sequence',
  title: 'Intermittent 502s and 504s: the keep-alive race and slow targets',
  desc: 'The load balancer keeps a pool of connections to each target and reuses them. When the target closes an idle connection first, a request can be sent into a socket that is already closing.',
  actors: [
    { id: 'c', label: 'Client', icon: '💻', color: 'gray' },
    { id: 'lb', label: 'ALB / App Gateway', sub: 'idle timeout 60 s', color: 'blue', info: 'ALB idle timeout defaults to 60 s and applies to both client and target connections. Deregistration delay (connection draining) defaults to 300 s.' },
    { id: 'go', label: 'Go target', sub: 'http.Server', icon: '🐹', color: 'green', info: 'Set IdleTimeout higher than the LB idle timeout (for example 75 s) and ReadHeaderTimeout to protect against slow clients. On SIGTERM, fail readiness, then call Shutdown(ctx) to finish in-flight requests.' },
  ],
  steps: [
    { section: 'Normal: pooled backend connection' },
    { from: 'c', to: 'lb', label: 'GET /orders', caption: 'The client request arrives at the load balancer, which terminates TLS and picks a healthy target.' },
    { from: 'lb', to: 'go', label: 'GET (pooled conn)', caption: 'The LB reuses an idle keep-alive connection to the target instead of opening a new TCP (and TLS) connection for every request.' },
    { from: 'go', to: 'lb', label: '200 OK', reply: true, caption: 'The target responds; the connection goes back into the LB pool.' },
    { from: 'lb', to: 'c', label: '200 OK', reply: true, caption: 'The response reaches the client. So far so good.' },
    { section: 'Race: the target closes first' },
    { from: 'go', to: 'go', label: 'idle 30 s: close', caption: 'The backend idle timeout is 30 s, shorter than the LB 60 s. After 30 idle seconds the target closes the pooled connection, but the LB has not noticed yet.' },
    { from: 'c', to: 'lb', label: 'GET /orders', caption: 'A new request arrives at that exact moment.' },
    { from: 'lb', to: 'go', label: 'reuse same conn', caption: 'The LB sends it on the connection it believes is still idle and open. The request crosses the FIN on the wire.' },
    { from: 'go', to: 'lb', label: 'RST', reply: true, caption: 'The target kernel answers with a reset because the socket is closed.' },
    { from: 'lb', to: 'c', label: '502 Bad Gateway', reply: true, caption: 'The LB returns 502. It is rare, random and load-dependent, which is why it is hard to reproduce. Fix: make the target idle timeout longer than the LB one so the LB always closes first.' },
    { section: 'Slow target: 504' },
    { from: 'lb', to: 'go', label: 'GET /report', caption: 'A request that takes longer than the LB idle timeout with no bytes sent back.' },
    { from: 'lb', to: 'c', label: '504 Gateway Timeout', reply: true, caption: 'After 60 s of silence the LB gives up and returns 504. Fix the slow path, make it asynchronous (202 + polling), or raise the idle timeout deliberately. API Gateway has its own 29 s integration timeout.' },
    { section: 'Deploys without errors' },
    { from: 'lb', to: 'lb', label: 'deregister + drain', caption: 'On scale-in or deploy the LB stops sending new requests to the target and waits up to the deregistration delay for in-flight ones.' },
    { from: 'go', to: 'go', label: 'SIGTERM: Shutdown', caption: 'The Go service fails readiness, finishes in-flight requests with http.Server.Shutdown(ctx) and exits before the platform grace period ends. Align the drain delay with that grace period.' },
  ],
});

registerDiagram({
  id: 'cloud-apigw-request-path',
  roadmap: 'cloud', module: 5, topic: 'Managed API Gateways: Amazon API Gateway vs Azure API Management',
  kind: 'sequence',
  title: 'One API request through WAF, API Gateway, an authorizer and the backend',
  desc: 'A managed gateway runs a fixed pipeline before your code sees a request: WAF, throttling, authorization, validation, then the integration. Each stage has its own failure code, which is what interviewers ask about.',
  actors: [
    { id: 'client', label: 'Client', sub: 'mobile app', icon: '📱', color: 'gray' },
    { id: 'waf', label: 'AWS WAF', sub: 'web ACL', color: 'red', info: 'Attached to a REST API stage (or to CloudFront in front of an HTTP API, which has no direct WAF association). Managed rule groups, IP reputation, rate-based rules and Bot Control. Blocked requests get 403 and never cost backend capacity.' },
    { id: 'apigw', label: 'API Gateway', sub: 'REST / HTTP API stage', color: 'purple', info: 'Azure API Management runs the same pipeline as XML policies: validate-jwt, rate-limit-by-key, quota-by-key, set-backend-service, retry, cache-lookup, at global, product, API and operation scope.' },
    { id: 'auth', label: 'Authorizer', sub: 'JWT or Lambda', color: 'orange', info: 'JWT authorizer (HTTP APIs): validates signature via the issuer JWKS, iss, aud, exp and scopes with no code. Lambda authorizer: your code returns allow/deny plus context; results are cached by token for a TTL. Cognito user pool and IAM (SigV4) authorizers also exist.' },
    { id: 'backend', label: 'Backend', sub: 'Lambda / VPC link', icon: '🐹', color: 'green' },
  ],
  steps: [
    { section: 'Edge and throttling' },
    { from: 'client', to: 'waf', label: 'POST /orders + JWT', caption: 'The client sends a request with a bearer token. TLS terminates at the API Gateway endpoint (edge-optimised endpoints sit behind CloudFront).' },
    { from: 'waf', to: 'waf', label: 'rules, rate limit', caption: 'The web ACL runs first: managed rules (SQLi, known bad inputs), IP reputation and a rate-based rule per IP. Matches are blocked with 403 before any gateway logic runs.' },
    { from: 'waf', to: 'apigw', label: 'allowed', caption: 'Allowed requests continue into the API Gateway pipeline for this stage and route.' },
    { from: 'apigw', to: 'apigw', label: 'token bucket', caption: 'Throttling: account-level regional limit (10,000 rps steady, 5,000 burst by default), then stage/route limits, then the usage plan of the API key (REST APIs). Over the limit returns 429 immediately.' },
    { section: 'Authorization and validation' },
    { from: 'apigw', to: 'auth', label: 'authorize(token)', caption: 'The authorizer checks who the caller is. A JWT authorizer verifies the signature, issuer, audience, expiry and scopes; a Lambda authorizer can call anything but adds latency, so cache its result.' },
    { from: 'auth', to: 'apigw', label: 'allow + context', reply: true, caption: 'Allowed, with context such as tenant ID and subject passed to the backend. A missing or invalid token gives 401; a valid token without permission gives 403.' },
    { from: 'apigw', to: 'apigw', label: 'validate + map', caption: 'REST APIs can validate the body against a JSON schema and transform it with mapping templates, rejecting malformed requests with 400 before they cost a backend invocation.' },
    { section: 'Integration' },
    { from: 'apigw', to: 'backend', label: 'invoke (29 s limit)', caption: 'The integration calls Lambda or a private service through a VPC link. The integration timeout defaults to 29 s (REST regional and private APIs can request more).' },
    { from: 'backend', to: 'apigw', label: '201 Created', reply: true, caption: 'The backend uses the authorizer context instead of re-parsing the token. Idempotency keys on POST make client retries safe.' },
    { from: 'apigw', to: 'client', label: '201 + access log', reply: true, caption: 'The response returns with CORS headers; access logs and metrics record latency, integration latency and status for each stage.' },
    { section: 'Failure paths' },
    { from: 'apigw', to: 'client', label: '429 Too Many Requests', reply: true, caption: 'Throttled clients should honour Retry-After and back off with jitter. Per-client fairness needs usage plans or APIM rate-limit-by-key; WAF rate rules only stop gross abuse per IP.' },
    { from: 'apigw', to: 'client', label: '504 Integration timeout', reply: true, caption: 'If the backend takes longer than the integration timeout the client gets 504 even if the work completes later. Long jobs should return 202 with a status URL and run asynchronously.' },
  ],
});

