registerDiagram({
  id: 'cloud-presigned-upload',
  roadmap: 'cloud', module: 6, problem: 'Let clients upload directly to storage with presigned URLs or SAS',
  kind: 'sequence',
  title: 'Direct-to-storage upload with a presigned URL or SAS, then async processing',
  desc: 'The API authorises the upload and signs a short-lived URL; the bytes go straight from the browser to S3 or Blob Storage, never through your Go service. A storage event then triggers processing.',
  actors: [
    { id: 'b', label: 'Browser', icon: '💻', color: 'gray' },
    { id: 'api', label: 'Go API', sub: 'holds role / identity', icon: '🐹', color: 'blue', info: 'Runs with an IAM role or managed identity that is allowed to write under uploads/. The presigned URL can never grant more than the signer has, and dies when the signer session expires.' },
    { id: 's3', label: 'S3 / Blob', sub: 'private bucket', icon: '🪣', color: 'green', info: 'Block Public Access on, CORS allowing PUT from your web origin only. Encryption at rest is on by default (SSE-S3 / Microsoft-managed keys).' },
    { id: 'ev', label: 'EventBridge / Grid', sub: 'ObjectCreated', color: 'purple' },
    { id: 'wk', label: 'Scanner worker', sub: 'Lambda / Function', color: 'orange' },
  ],
  steps: [
    { section: 'Authorise and sign' },
    { from: 'b', to: 'api', label: 'POST /uploads (JWT)', caption: 'The browser asks to upload, sending its user token plus the intended file name, content type and size. Only the API decides whether this user may upload this kind of file.' },
    { from: 'api', to: 'api', label: 'authz + validate', caption: 'The API checks the user, the type and the size limit, and chooses the object key itself (uploads/user-42/uuid). Letting the client pick the key would let it overwrite other objects.' },
    { from: 'api', to: 'api', label: 'presign PUT, 5 min', caption: 'S3: a SigV4 presigned PUT, computed locally with the role credentials and no AWS call. Use presigned POST to enforce a max size. Azure: fetch a user delegation key from Entra-authorised Storage, then sign a create/write-only SAS.' },
    { from: 'api', to: 'b', label: 'URL + key', reply: true, caption: 'The response carries a URL that allows one operation on one key for a few minutes. Never return account keys or long-lived SAS tokens.' },
    { section: 'Upload direct to storage' },
    { from: 'b', to: 's3', label: 'PUT bytes (signed URL)', caption: 'The browser uploads straight to storage. Your API does not proxy gigabytes, so it needs no extra memory or bandwidth and scales independently. Large files use multipart uploads or staged blocks.' },
    { from: 's3', to: 's3', label: 'verify sig, expiry', caption: 'Storage recomputes the signature, checks the expiry and the signed headers (content type), then evaluates the signer permissions. A tampered URL or a wrong Content-Type fails with 403.' },
    { from: 's3', to: 'b', label: '200 + ETag', reply: true, caption: 'The object is stored with strong read-after-write consistency.' },
    { section: 'Process asynchronously' },
    { from: 's3', to: 'ev', label: 'ObjectCreated', caption: 'Storage emits an event: S3 to EventBridge (or SQS), Blob Storage to Event Grid BlobCreated. Processing is decoupled from the upload request.' },
    { from: 'ev', to: 'wk', label: 'event (at least once)', caption: 'The worker receives the event. Delivery is at least once, so processing must be idempotent: key the work on bucket, key and version or ETag.' },
    { from: 'wk', to: 's3', label: 'GET, scan, thumbnail', caption: 'The worker scans for malware, validates the real content type and creates derivatives. Until then the object stays in a quarantine prefix that users cannot read.' },
    { from: 'wk', to: 'api', label: 'mark upload ready', caption: 'The worker records the result; the API now serves the file, typically through another short-lived presigned GET or CDN signed URL.' },
  ],
});

registerDiagram({
  id: 'cloud-s3-lifecycle',
  roadmap: 'cloud', module: 6, topic: 'Lifecycle, Versioning, Immutability and Redundancy',
  kind: 'graph',
  title: 'An object ages through storage classes: lifecycle rules on S3 and Blob',
  desc: 'Lifecycle rules move objects to cheaper classes as access drops, then delete them. Each colder class trades lower storage price for retrieval fees, minimum storage durations and slower access. Azure tiers in brackets.',
  nodes: [
    { id: 'put', label: 'PUT object', sub: 'logs/2026/10/29', x: 0, y: 1, shape: 'pill', color: 'gray' },
    { id: 'std', label: 'S3 Standard', sub: '(Hot) · day 0', x: 1.3, y: 1, w: 1.1, color: 'green', info: 'Highest storage price, no retrieval fee, no minimum duration. Multi-AZ by default on S3; on Azure redundancy (LRS, ZRS, GRS, GZRS) is an account setting independent of the tier.' },
    { id: 'ia', label: 'Standard-IA', sub: '(Cool) · min 30 d', x: 2.6, y: 1, w: 1.1, color: 'teal', info: 'Cheaper storage, per-GB retrieval fee, 30-day minimum and a 128 KB minimum billable object size on S3. One Zone-IA is cheaper still but lives in a single AZ.' },
    { id: 'gir', label: 'Glacier IR', sub: '(Cold) · min 90 d', x: 3.9, y: 1, w: 1.1, color: 'blue', info: 'Glacier Instant Retrieval still returns data in milliseconds but has higher retrieval fees and a 90-day minimum. Azure Cold tier is the close equivalent.' },
    { id: 'deep', label: 'Deep Archive', sub: '(Archive) · min 180 d', x: 5.2, y: 1, w: 1.1, color: 'purple', info: 'Cheapest storage, offline. S3 Glacier Deep Archive restores in 12 to 48 hours (Glacier Flexible Retrieval: minutes to hours); Azure Archive rehydrates in up to about 15 hours, or under an hour for small blobs with high priority.' },
    { id: 'exp', label: 'Expire', sub: 'delete at 7 years', x: 6.5, y: 1, color: 'gray', info: 'On a versioned bucket, expiring the current version only adds a delete marker; a separate noncurrent-version rule removes the data. Object Lock or immutability policies block deletion until retention ends.' },
    { id: 'versions', label: 'Old versions', sub: 'expire after 30 d', x: 1.3, y: 2.6, w: 1.1, color: 'yellow' },
    { id: 'mpu', label: 'Incomplete MPU', sub: 'abort after 7 d', x: 2.6, y: 2.6, w: 1.1, color: 'yellow', info: 'Parts of multipart uploads that were never completed are billed but invisible in listings. An AbortIncompleteMultipartUpload rule on every bucket is free money.' },
    { id: 'it', label: 'Intelligent-Tiering', sub: 'unknown access', x: 3.9, y: 2.6, w: 1.1, color: 'orange', info: 'Moves each object between access tiers automatically based on its own access, for a small per-object monitoring fee and with no retrieval fees. Azure: lifecycle rules on last access time, which can also move a blob back to Hot when it is read.' },
    { id: 'restore', label: 'Restore copy', sub: 'hours · temporary', x: 5.2, y: 2.6, w: 1.1, color: 'purple' },
  ],
  edges: [
    { from: 'put', to: 'std' },
    { from: 'std', to: 'ia' },
    { from: 'ia', to: 'gir' },
    { from: 'gir', to: 'deep' },
    { from: 'deep', to: 'exp' },
    { from: 'deep', to: 'restore', label: 'restore request' },
    { from: 'std', to: 'versions', label: 'overwrites', dashed: true },
    { from: 'put', to: 'mpu', dashed: true },
  ],
  steps: [
    { caption: 'New log objects land in S3 Standard (Azure Hot): instant access, no retrieval fee, highest storage price. For the first weeks they are read often, so that is the right place.', flows: [{ from: 'put', to: 'std', label: 'day 0' }] },
    { caption: 'Day 30: a transition rule moves them to Standard-IA (Cool). Storage is cheaper but every GB read costs money, and objects deleted before 30 days are billed for 30 anyway.', flows: [{ from: 'std', to: 'ia', label: 'day 30' }] },
    { caption: 'Day 90: Glacier Instant Retrieval (Cold). Still millisecond reads, cheaper storage, higher retrieval fees and a 90-day minimum. Good for data read a few times a year.', flows: [{ from: 'ia', to: 'gir', label: 'day 90' }] },
    { caption: 'Day 365: Deep Archive (Archive). The cheapest tier, but the data is offline. Use it for compliance copies you hope never to read; early deletion before 180 days is still charged.', flows: [{ from: 'gir', to: 'deep', label: 'day 365' }] },
    { caption: 'Reading archived data needs a restore (S3 creates a temporary copy) or a rehydration to Hot or Cool (Azure), taking hours. Make sure the RTO for that data tolerates it.', flows: [{ from: 'deep', to: 'restore', label: 'restore' }] },
    { caption: 'After the retention period an expiration rule deletes the object. With versioning on, add a noncurrent-version expiration too, otherwise the old data keeps billing behind a delete marker.', flows: [{ from: 'deep', to: 'exp', label: 'year 7' }] },
    { caption: 'Hygiene rules every bucket should have: expire noncurrent versions after N days and abort incomplete multipart uploads after 7 days. Both are invisible costs until someone reads the bill.', flows: [{ from: 'std', to: 'versions', label: 'old version' }, { from: 'put', to: 'mpu', label: 'failed upload' }] },
    { caption: 'If access is unpredictable, Intelligent-Tiering (or Azure last-access rules) decides per object. Transitions cost a request each, so moving millions of tiny objects to a cold tier can cost more than it saves.', active: ['it'] },
  ],
});

