registerDiagram({
  id: 'cloud-rds-multi-az-replicas',
  roadmap: 'cloud', module: 7, problem: 'Multi-AZ vs read replicas: which problem does each solve?',
  kind: 'graph',
  title: 'Multi-AZ standby vs read replicas, and what happens on AZ failure',
  desc: 'A Multi-AZ standby is a synchronous copy for availability; read replicas are asynchronous copies for read scaling and DR. Play it to see both, then a failover.',
  groups: [
    { id: 'region', label: 'Region', x: 2.5, y: 0, w: 4.5, h: 3.7, color: 'blue' },
    { id: 'aza', label: 'AZ a', x: 2.6, y: 0.4, w: 1.4, h: 3.1, color: 'gray' },
    { id: 'azb', label: 'AZ b', x: 4.1, y: 0.4, w: 1.4, h: 3.1, color: 'gray' },
    { id: 'azc', label: 'AZ c', x: 5.6, y: 0.4, w: 1.35, h: 3.1, color: 'gray' },
  ],
  nodes: [
    { id: 'app', label: 'Go app', sub: 'pgx pool', icon: '🐹', x: 0, y: 1.5, color: 'gray', info: 'Must reconnect on failure and must not cache the resolved IP longer than the DNS TTL. RDS Proxy keeps client connections open across a failover and shortens it.' },
    { id: 'wep', label: 'Writer endpoint', sub: 'DNS CNAME', x: 1.3, y: 0.5, color: 'blue' },
    { id: 'rep', label: 'Replica endpoint', sub: 'reads only', x: 1.3, y: 2.5, color: 'teal' },
    { id: 'primary', label: 'Primary', sub: 'read + write', x: 2.8, y: 0.8, shape: 'db', color: 'blue', exit: 5 },
    { id: 'standby', label: 'Standby', sub: 'sync · not readable', x: 4.3, y: 0.8, shape: 'db', color: 'purple', exit: 6, info: 'Multi-AZ instance deployment: a synchronous standby you cannot read from. A Multi-AZ DB cluster instead has two readable standbys and faster failover. Azure Flexible Server: zone-redundant HA.' },
    { id: 'replica', label: 'Read replica', sub: 'async · may lag', x: 5.75, y: 2.4, shape: 'db', color: 'teal', info: 'Asynchronous, readable, can be in another AZ or region. Watch ReplicaLag. Aurora replicas share the storage volume, lag only milliseconds and double as failover targets.' },
    { id: 'newprim', label: 'New primary', sub: 'promoted standby', x: 4.3, y: 2.3, shape: 'db', color: 'blue', enter: 6, info: 'The former standby, now serving reads and writes behind the same writer endpoint. Its data is identical to the old primary up to the last acknowledged commit because replication was synchronous.' },
    { id: 'newsb', label: 'New standby', sub: 'rebuilt · sync', x: 5.75, y: 0.8, shape: 'db', color: 'purple', ghost: true, enter: 6, info: 'RDS automatically creates a replacement standby in a healthy AZ, so the deployment is Multi-AZ again. Until it is in sync, an AZ failure would mean a longer recovery from backups.' },
    { id: 'xr', label: 'DR replica', sub: 'other region · async', x: 5.75, y: 5, shape: 'db', color: 'orange', ghost: true, info: 'A cross-region read replica is promoted manually for DR. Aurora Global Database and Azure SQL failover groups manage cross-region switchover and failover for you.' },
  ],
  edges: [
    { from: 'app', to: 'wep' },
    { from: 'app', to: 'rep' },
    { from: 'wep', to: 'primary' },
    { from: 'rep', to: 'replica', label: 'reads', curve: 40 },
    { from: 'primary', to: 'standby', label: 'sync' },
    { from: 'primary', to: 'replica', label: 'async' },
    { from: 'primary', to: 'xr', label: 'async (DR)', dashed: true, curve: 60 },
    { from: 'newprim', to: 'replica' },
    { from: 'newprim', to: 'newsb', label: 'sync', dashed: true },
  ],
  steps: [
    { caption: 'The app writes through the writer endpoint, a DNS name that points at the current primary. Applications should never hard-code the instance address.', flows: [{ from: 'app', to: 'wep', label: 'INSERT' }, { from: 'wep', to: 'primary' }] },
    { caption: 'Multi-AZ: every commit is replicated synchronously to the standby in another AZ before it is acknowledged. RPO is zero for an AZ failure, at the cost of a little write latency. The standby serves no reads.', flows: [{ from: 'primary', to: 'standby', label: 'commit log' }] },
    { caption: 'Read replicas scale reads. Replication is asynchronous, so a replica can lag: a user who writes and immediately reads from a replica may not see their change (read-your-writes). Send those reads to the writer.', flows: [{ from: 'app', to: 'rep', label: 'SELECT' }, { from: 'rep', to: 'replica' }, { from: 'primary', to: 'replica', label: 'async' }] },
    { caption: 'A cross-region replica protects against a region outage. It is asynchronous, so RPO is the lag at the moment of failure, and promotion is a deliberate step.', flows: [{ from: 'primary', to: 'xr', label: 'async (DR)' }] },
    { caption: 'AZ a fails and the primary is gone. RDS detects it, promotes the standby, and repoints the writer endpoint DNS. Typical time for a Multi-AZ instance is 60-120 s; no committed data is lost because replication was synchronous.', active: ['aza', 'standby', 'wep'] },
    { caption: 'The standby is now the primary. Writes resume once the app reconnects and resolves the new address; RDS then builds a fresh standby in another AZ. The read replica re-attaches to the new primary and keeps serving reads.', flows: [{ from: 'app', to: 'wep', label: 'reconnect' }, { from: 'wep', to: 'newprim', label: 'writes' }, { from: 'newprim', to: 'replica', label: 'async' }, { from: 'newprim', to: 'newsb', label: 'sync' }] },
    { caption: 'Summary: Multi-AZ = availability (sync, not readable); replicas = read scale and DR (async, readable). Aurora blurs the line: replicas share storage and are failover targets. Azure: zone-redundant HA, read replicas, Business Critical readable secondary.', active: ['newprim', 'newsb', 'replica', 'xr'] },
  ],
});

registerDiagram({
  id: 'cloud-dynamodb-partitions',
  roadmap: 'cloud', module: 7, topic: 'DynamoDB: Keys, Partitions, Indexes, Capacity and Streams',
  kind: 'graph',
  title: 'DynamoDB partitions, hot keys, GSIs and Streams',
  desc: 'The partition key is hashed to pick a physical partition, and each partition has its own throughput ceiling. Play it to see a well-keyed query, a hot key, a GSI and a stream.',
  groups: [
    { id: 'table', label: 'Table: Orders', x: 3, y: 0, w: 1.6, h: 5, color: 'teal' },
  ],
  nodes: [
    { id: 'app', label: 'Go service', icon: '🐹', x: 0, y: 2, color: 'gray' },
    { id: 'router', label: 'Request router', sub: 'hash(PK) → partition', x: 1.5, y: 2, color: 'blue', info: 'Hashes the partition key to find the partition, then sends the request to its storage nodes. Each partition is stored on three replicas in three AZs; a write is acknowledged once two replicas have it durably.' },
    { id: 'p1', label: 'Partition 1', sub: '≤3k RCU · 1k WCU', x: 3.3, y: 0.5, color: 'teal', info: 'Each physical partition serves up to about 3,000 RCU, 1,000 WCU and 10 GB. Adaptive capacity and split-for-heat help with uneven load, but a single hot key is still capped.' },
    { id: 'p2', label: 'Partition 2', sub: '≤3k RCU · 1k WCU', x: 3.3, y: 2, color: 'teal' },
    { id: 'p3', label: 'Partition 3', sub: '≤3k RCU · 1k WCU', x: 3.3, y: 3.5, color: 'teal' },
    { id: 'gsi', label: 'GSI byStatus', sub: 'async · own capacity', x: 5.5, y: 0.5, color: 'purple', info: 'A global secondary index is a separate table keyed differently, updated asynchronously and readable only with eventual consistency. Up to 20 per table, addable at any time. LSIs must be created with the table and cap each partition-key value at 10 GB.' },
    { id: 'stream', label: 'DynamoDB Stream', sub: '24 h change log', x: 5.5, y: 2, color: 'orange' },
    { id: 'lam', label: 'Lambda consumer', sub: 'projections, outbox', x: 5.5, y: 3.5, color: 'orange' },
  ],
  edges: [
    { from: 'app', to: 'router' },
    { from: 'router', to: 'p1' },
    { from: 'router', to: 'p2' },
    { from: 'router', to: 'p3' },
    { from: 'p2', to: 'gsi', label: 'async' },
    { from: 'p2', to: 'stream' },
    { from: 'stream', to: 'lam' },
  ],
  steps: [
    { caption: 'PutItem PK=USER#42, SK=ORDER#2026-10-29. The router hashes USER#42 to partition 2. Items with the same partition key live together, sorted by sort key. 1 WCU covers one write per second of up to 1 KB.', flows: [{ from: 'app', to: 'router', label: 'PutItem' }, { from: 'router', to: 'p2', label: 'USER#42' }] },
    { caption: 'Query PK=USER#42 AND begins_with(SK, "ORDER#") reads one partition and returns a sorted range: one request, predictable latency. A Scan would read every partition and is not for request paths.', flows: [{ from: 'app', to: 'router', label: 'Query' }, { from: 'router', to: 'p2', label: 'one partition' }] },
    { caption: 'Hot key: every new order also writes PK=STATUS#PENDING. All of those land on partition 1, which throttles at about 1,000 WCU even though the table as a whole has plenty of capacity.', flows: [{ from: 'router', to: 'p1', label: 'STATUS#PENDING', color: 'red' }], active: ['p1'] },
    { caption: 'Fix with high-cardinality keys or write sharding (STATUS#PENDING#0..9, read with a parallel query per shard). CloudWatch Contributor Insights shows the most-accessed keys when you debug throttling.', flows: [{ from: 'router', to: 'p1', label: 'shard 0-3' }, { from: 'router', to: 'p2', label: 'shard 4-6' }, { from: 'router', to: 'p3', label: 'shard 7-9' }] },
    { caption: 'A GSI with a different key (status, createdAt) is updated asynchronously from the base table. If the GSI lacks capacity, it throttles writes to the base table too.', flows: [{ from: 'p2', to: 'gsi', label: 'propagate' }] },
    { caption: 'DynamoDB Streams records every change per item in order for 24 hours. Lambda consumes it to build projections, publish events (an outbox without a second write) or feed search.', flows: [{ from: 'p2', to: 'stream', label: 'new + old image' }, { from: 'stream', to: 'lam', label: 'batch' }] },
    { caption: 'Cosmos DB uses the same idea: a logical partition (one key value) caps at 20 GB, physical partitions serve up to 10,000 RU/s, and a 429 with retry-after signals a hot partition or too little throughput.', active: ['p1', 'p2', 'p3'] },
  ],
});

