registerDiagram({
  id: 'cloud-sns-sqs-fanout',
  roadmap: 'cloud', module: 8, topic: 'Pub/Sub and Fan-out: SNS and Service Bus Topics',
  kind: 'graph',
  title: 'SNS to SQS fan-out with filter policies and a dead-letter queue',
  desc: 'One published event, many independent consumers, each with its own durable queue. Azure equivalent: a Service Bus topic with one subscription per consumer, each with a built-in dead-letter sub-queue.',
  nodes: [
    { id: 'prod', label: 'Order service', sub: 'publisher', icon: '🐹', x: 0, y: 1.5, color: 'blue', info: 'Publishes OrderPlaced once, with message attributes such as status and amount. It does not know who consumes the event.' },
    { id: 'sns', label: 'SNS topic', sub: 'Azure: SB topic', x: 1.5, y: 1.5, color: 'purple', info: 'Each subscription can have a filter policy on message attributes or body. Enable raw message delivery so consumers get the original payload without the SNS envelope. SNS FIFO + SQS FIFO preserves order per message group.' },
    { id: 'q1', label: 'billing queue', sub: 'SQS', x: 3.5, y: 0, color: 'orange', info: 'The queue access policy must allow sns.amazonaws.com with aws:SourceArn = the topic ARN (confused-deputy protection). With SSE-KMS, the key policy must allow SNS too.' },
    { id: 'q2', label: 'shipping queue', sub: 'filter: paid', x: 3.5, y: 1.5, color: 'orange' },
    { id: 'q3', label: 'analytics queue', sub: 'SQS', x: 3.5, y: 3, color: 'orange' },
    { id: 'c1', label: 'billing workers', x: 5.5, y: 0, color: 'green' },
    { id: 'c2', label: 'shipping workers', x: 5.5, y: 1.5, color: 'green', info: 'Long-poll (20 s), process, then delete. The visibility timeout must exceed processing time, or extend it with ChangeMessageVisibility while working.' },
    { id: 'c3', label: 'analytics loader', x: 5.5, y: 3, color: 'green' },
    { id: 'dlq', label: 'shipping DLQ', sub: 'alarm on depth', x: 5.5, y: 4.5, color: 'red', info: 'A redrive policy moves a message here after maxReceiveCount failed receives. Alarm on ApproximateNumberOfMessagesVisible, fix the bug, then redrive the messages back to the source queue.' },
  ],
  edges: [
    { from: 'prod', to: 'sns' },
    { from: 'sns', to: 'q1', label: 'all' },
    { from: 'sns', to: 'q2', label: 'status=paid' },
    { from: 'sns', to: 'q3', label: 'all' },
    { from: 'q1', to: 'c1' },
    { from: 'q2', to: 'c2' },
    { from: 'q3', to: 'c3' },
    { from: 'q2', to: 'dlq', label: 'maxReceiveCount 5' },
  ],
  steps: [
    { caption: 'The order service publishes OrderPlaced once. Adding a new consumer later needs no change to the producer.', flows: [{ from: 'prod', to: 'sns', label: 'OrderPlaced' }] },
    { caption: 'SNS delivers a copy to every subscribed queue whose filter policy matches. Shipping only wants paid orders, so a pending order never reaches its queue. Filtering at the topic saves consumers from discarding messages.', flows: [{ from: 'sns', to: 'q1', label: 'copy' }, { from: 'sns', to: 'q3', label: 'copy' }], active: ['q2'] },
    { caption: 'A paid order matches all three filters. Each queue holds its own durable copy, so a slow or broken consumer never blocks the others.', flows: [{ from: 'sns', to: 'q1' }, { from: 'sns', to: 'q2', label: 'status=paid' }, { from: 'sns', to: 'q3' }] },
    { caption: 'Consumers poll their own queue and scale on its depth. A received message is hidden for the visibility timeout; the worker deletes it only after successful processing.', flows: [{ from: 'q1', to: 'c1', label: 'receive' }, { from: 'q2', to: 'c2', label: 'receive' }, { from: 'q3', to: 'c3', label: 'receive' }] },
    { caption: 'A malformed message makes the shipping worker crash each time. It becomes visible again and is retried; after 5 receives the redrive policy moves it to the DLQ so it stops blocking the queue and burning retries.', flows: [{ from: 'q2', to: 'c2', label: 'retry', color: 'red' }, { from: 'q2', to: 'dlq', label: 'poison', color: 'red' }] },
    { caption: 'Delivery is at least once, so every consumer must be idempotent: record processed event IDs with a conditional write, or make the operation naturally idempotent (upsert, set state).', active: ['c1', 'c2', 'c3'] },
    { caption: 'Azure: a Service Bus topic with SQL or correlation filters per subscription; each subscription has peek-lock, sessions for ordering and a dead-letter sub-queue after max delivery count (default 10).', active: ['sns', 'q1', 'q2', 'q3', 'dlq'] },
  ],
});

registerDiagram({
  id: 'cloud-eventbridge-routing',
  roadmap: 'cloud', module: 8, topic: 'Event Routing: Amazon EventBridge and Azure Event Grid',
  kind: 'graph',
  title: 'EventBridge: sources, a bus, pattern rules, targets, DLQ and replay',
  desc: 'Producers put events on a bus without knowing who listens. Rules match event patterns and push copies to targets, with retries, a dead-letter queue and an archive for replay. Azure Event Grid follows the same shape with topics and subscriptions.',
  nodes: [
    { id: 'orders', label: 'Orders service', sub: 'PutEvents', icon: '🐹', x: 0, y: 0.5, color: 'blue', info: 'Publishes OrderPlaced with source com.acme.orders, a detail-type and a versioned detail payload (event-carried state). It never calls consumers directly, so adding one needs no producer change.' },
    { id: 'awssvc', label: 'AWS services', sub: 'S3 Object Created', x: 0, y: 2, color: 'gray', info: 'AWS service events (S3 with EventBridge notifications enabled, EC2 state changes, CloudTrail API calls) arrive on the default bus in each account and region. A rule there can forward them to a custom or cross-account bus.' },
    { id: 'saas', label: 'SaaS partner', sub: 'partner event source', x: 0, y: 3.5, color: 'gray' },
    { id: 'bus', label: 'Event bus', sub: 'custom: orders', x: 2, y: 2, color: 'purple', info: 'Buses can receive events from other accounts (resource policy), and rules can target buses in other accounts or regions for central routing. Related features: Pipes (point-to-point source, filter, enrich, target) and Scheduler.' },
    { id: 'archive', label: 'Archive', sub: 'replay window', x: 2, y: 3.5, color: 'teal' },
    { id: 'r1', label: 'Rule: big orders', sub: 'total >= 1000', x: 3.7, y: 0.5, shape: 'diamond', w: 1.3, color: 'orange' },
    { id: 'r2', label: 'Rule: all orders', sub: 'detail-type match', x: 3.7, y: 2, shape: 'diamond', w: 1.3, color: 'orange' },
    { id: 'r3', label: 'Rule: uploads', sub: 'prefix incoming/', x: 3.7, y: 3.5, shape: 'diamond', w: 1.3, color: 'orange' },
    { id: 't1', label: 'Step Functions', sub: 'fraud review', x: 5.6, y: 0.5, color: 'green' },
    { id: 't2', label: 'SQS queue', sub: 'billing · buffered', x: 5.6, y: 2, color: 'green', info: 'Put a queue in front of consumers that need buffering, batching or controlled concurrency. The queue policy must allow events.amazonaws.com with aws:SourceArn = the rule ARN.' },
    { id: 't3', label: 'Lambda', sub: 'thumbnail', x: 5.6, y: 3.5, color: 'green' },
    { id: 'dlq', label: 'Rule DLQ', sub: 'SQS · alarm on depth', x: 5.6, y: 5, color: 'red', info: 'After the retry policy is exhausted (default 24 hours and 185 attempts, both configurable) or on non-retryable errors, the event goes to the target DLQ with error attributes. Without a DLQ it is dropped.' },
    { id: 'eg', label: 'Azure Event Grid', sub: 'topics + subscriptions', x: 0, y: 5, w: 1.5, color: 'gray', ghost: true, info: 'System topics (Blob Created, resource changes), custom topics and namespaces; event subscriptions with subject and advanced filters push to Functions, webhooks, Service Bus, Event Hubs or Storage queues, retry for up to 24 hours and dead-letter to Blob. CloudEvents 1.0 is the recommended schema.' },
  ],
  edges: [
    { from: 'orders', to: 'bus' },
    { from: 'awssvc', to: 'bus' },
    { from: 'saas', to: 'bus' },
    { from: 'bus', to: 'r1' },
    { from: 'bus', to: 'r2' },
    { from: 'bus', to: 'r3' },
    { from: 'r1', to: 't1' },
    { from: 'r2', to: 't2' },
    { from: 'r3', to: 't3' },
    { from: 'r3', to: 'dlq', label: 'after retries', dashed: true },
    { from: 'bus', to: 'archive', dashed: true },
  ],
  steps: [
    { caption: 'The orders service calls PutEvents with source, detail-type and detail. It neither knows nor cares who consumes the event: that decoupling is the point of an event router.', flows: [{ from: 'orders', to: 'bus', label: 'OrderPlaced' }] },
    { caption: 'Every rule on the bus evaluates its JSON event pattern (exact, prefix, numeric, exists, anything-but). One event can match several rules; this large order matches two.', flows: [{ from: 'bus', to: 'r1', label: 'match' }, { from: 'bus', to: 'r2', label: 'match' }] },
    { caption: 'Each matching rule pushes a copy to its targets (up to five per rule): the big order starts a fraud-review workflow, and every order is buffered in the billing queue.', flows: [{ from: 'r1', to: 't1', label: 'start execution' }, { from: 'r2', to: 't2', label: 'SendMessage' }] },
    { caption: 'AWS service events work the same way: an S3 Object Created event for the incoming/ prefix matches the uploads rule and invokes the thumbnail Lambda asynchronously.', flows: [{ from: 'awssvc', to: 'bus', label: 'Object Created' }, { from: 'bus', to: 'r3' }, { from: 'r3', to: 't3', label: 'invoke' }] },
    { caption: 'The Lambda is throttled or failing. EventBridge retries with backoff for up to 24 hours, then moves the event to the rule target DLQ. Alarm on its depth; without a DLQ the event is silently dropped.', flows: [{ from: 'r3', to: 't3', label: 'retry', color: 'red' }, { from: 'r3', to: 'dlq', label: 'give up', color: 'red' }] },
    { caption: 'The archive keeps matching events. After fixing a consumer bug, replay a time window back onto the bus. Replayed events are redelivered, so every consumer must be idempotent on the event ID.', flows: [{ from: 'bus', to: 'archive', label: 'archive' }, { from: 'archive', to: 'bus', label: 'replay' }] },
    { caption: 'Delivery is at least once and not ordered. Include an event ID and timestamp, version the schema (the schema registry helps), and keep events about facts, not commands addressed to one consumer.', active: ['orders', 't1', 't2', 't3'] },
    { caption: 'Azure Event Grid: system or custom topics, event subscriptions with filters, push delivery with retries for up to 24 hours and dead-lettering to Blob storage. Namespaces add pull delivery and MQTT.', active: ['eg'] },
  ],
});

registerDiagram({
  id: 'cloud-step-functions-saga',
  roadmap: 'cloud', module: 8, problem: 'Design an order-processing saga across payment, inventory and shipping',
  kind: 'graph',
  title: 'Orchestrated saga in Step Functions: forward steps and compensations',
  desc: 'Each step is a local transaction in its own service. If a later step fails, the workflow runs compensating actions in reverse order instead of a distributed rollback. Play the happy path, then two failures.',
  nodes: [
    { id: 'start', label: 'Order placed', sub: 'start execution', x: 1.5, y: 0, shape: 'pill', color: 'gray', info: 'A Standard workflow: exactly-once state transitions, executions up to one year, and a full execution history you can inspect. Express workflows (at-least-once, 5 minutes max) are wrong for long sagas.' },
    { id: 'reserve', label: 'ReserveInventory', sub: 'retry 3x · backoff', x: 1.5, y: 1.2, color: 'blue', info: 'Retry with exponential backoff and jitter on transient errors (timeouts, throttling). Business errors such as OutOfStock should not be retried: catch them and fail fast.' },
    { id: 'charge', label: 'ChargePayment', sub: 'idempotency key', x: 1.5, y: 2.4, color: 'blue', info: 'Pass an idempotency key derived from the order ID to the payment provider, so a retried call after a timeout can never charge twice.' },
    { id: 'ship', label: 'CreateShipment', sub: 'waitForTaskToken', x: 1.5, y: 3.6, color: 'blue', info: 'The .waitForTaskToken integration sends a message with a task token and pauses the execution (no compute running) until the shipping service calls SendTaskSuccess or SendTaskFailure, or the timeout fires.' },
    { id: 'done', label: 'Order confirmed', sub: 'Succeed', x: 1.5, y: 4.8, shape: 'pill', color: 'green' },
    { id: 'failed', label: 'OrderFailed', sub: 'Fail · notify user', x: 4, y: 1.2, shape: 'pill', color: 'red' },
    { id: 'release', label: 'ReleaseInventory', sub: 'compensation', x: 4, y: 2.4, color: 'orange', info: 'Compensations are business-level undo operations, not database rollbacks. They must be idempotent and retried until they succeed; if one keeps failing, alert a human rather than leave the order half-done.' },
    { id: 'refund', label: 'RefundPayment', sub: 'compensation', x: 4, y: 3.6, color: 'orange' },
    { id: 'shipper', label: 'Shipping service', sub: 'SendTaskSuccess', x: 4, y: 4.8, w: 1.5, color: 'gray' },
  ],
  edges: [
    { from: 'start', to: 'reserve' },
    { from: 'reserve', to: 'charge' },
    { from: 'charge', to: 'ship' },
    { from: 'ship', to: 'done' },
    { from: 'reserve', to: 'failed', label: 'Catch' },
    { from: 'charge', to: 'release', label: 'Catch' },
    { from: 'ship', to: 'refund', label: 'Catch / timeout' },
    { from: 'refund', to: 'release' },
    { from: 'release', to: 'failed' },
    { from: 'ship', to: 'shipper', label: 'task token' },
  ],
  steps: [
    { caption: 'An OrderPlaced event (or API call) starts one execution per order. Using the order ID as the execution name makes the start idempotent: a duplicate start is rejected.', flows: [{ from: 'start', to: 'reserve', label: 'execution' }] },
    { caption: 'ReserveInventory runs a local transaction in the inventory service. Transient failures are retried with backoff and jitter; the state machine, not your code, owns the retry policy.', flows: [{ from: 'reserve', to: 'charge', label: 'reserved' }] },
    { caption: 'ChargePayment calls the payment provider with an idempotency key. Each step commits on its own: there is no distributed transaction or two-phase commit across services.', flows: [{ from: 'charge', to: 'ship', label: 'charged' }] },
    { caption: 'CreateShipment sends a task token to the shipping service and the execution pauses, for hours if needed, at no compute cost. The shipping service reports back with SendTaskSuccess.', flows: [{ from: 'ship', to: 'shipper', label: 'task token' }, { from: 'shipper', to: 'ship', label: 'success' }] },
    { caption: 'Happy path: every local transaction committed and the order is confirmed. The execution history shows exactly what happened and when, which choreography cannot give you for free.', flows: [{ from: 'ship', to: 'done', label: 'confirmed' }] },
    { caption: 'Payment declined: the Catch on ChargePayment jumps to ReleaseInventory, the compensation for the only step that already committed, and the order fails cleanly.', flows: [{ from: 'charge', to: 'release', label: 'declined', color: 'red' }, { from: 'release', to: 'failed', label: 'compensated' }] },
    { caption: 'Shipment never confirmed within the timeout: compensations run in reverse order, refund first, then release stock. Each compensation is idempotent and retried, because it must eventually succeed.', flows: [{ from: 'ship', to: 'refund', label: 'timeout', color: 'red' }, { from: 'refund', to: 'release', label: 'refunded' }, { from: 'release', to: 'failed' }] },
    { caption: 'Sagas give up isolation: others can see reserved stock or a charge that will be refunded. Model visible pending states, use semantic locks, and order steps so the hardest to undo (shipping) comes last. Azure: a Durable Functions orchestrator with try/catch does the same.', active: ['reserve', 'charge', 'ship', 'release', 'refund'] },
  ],
});

