registerDiagram({
  id: 'cloud-terraform-state-lock',
  roadmap: 'cloud', module: 9, topic: 'State, Remote Backends, Locking and Drift',
  kind: 'sequence',
  title: 'Terraform plan and apply with a remote S3 backend and lock file',
  desc: 'State maps every resource address to a real cloud object. The lock makes sure only one run can change it at a time. Azure: an azurerm backend uses a blob lease instead of a lock file.',
  actors: [
    { id: 'ci', label: 'CI job A', icon: '🤖', color: 'gray' },
    { id: 'tf', label: 'terraform', sub: 'CLI', color: 'purple' },
    { id: 's3', label: 'S3 backend', sub: 'state + .tflock', icon: '🪣', color: 'teal', info: 'Versioned, SSE-KMS encrypted, Block Public Access, ideally in a separate state account. use_lockfile = true (Terraform 1.10+) replaces the deprecated DynamoDB lock table.' },
    { id: 'api', label: 'AWS / Azure APIs', color: 'blue' },
    { id: 'ci2', label: 'CI job B', icon: '🤖', color: 'gray' },
  ],
  steps: [
    { section: 'Plan' },
    { from: 'ci', to: 'tf', label: 'plan -out=tfplan', caption: 'The pipeline runs terraform plan with an OIDC-assumed role. init has already downloaded the pinned providers and configured the backend.' },
    { from: 'tf', to: 's3', label: 'create .tflock', caption: 'Terraform writes the lock object with a conditional PUT (If-None-Match), which fails if the object already exists. That atomic create is what makes the lock safe. Azure takes a lease on the state blob.' },
    { from: 's3', to: 'tf', label: 'lock acquired', reply: true, caption: 'The lock records who holds it, when, and which operation, which is exactly what you read when you see a lock error.' },
    { from: 'tf', to: 's3', label: 'GET state', caption: 'Terraform reads the current state: resource addresses mapped to real IDs and cached attributes. State can contain secrets, so access to the bucket is as sensitive as the secrets themselves.' },
    { from: 'tf', to: 'api', label: 'refresh: read real resources', caption: 'It refreshes by reading each resource from the cloud APIs. Differences between state and reality are drift, for example a console hotfix.' },
    { from: 'tf', to: 'tf', label: 'diff → tfplan', caption: 'Desired config is compared with refreshed state. Look for -/+ (replace): on a database or subnet it means destroy and recreate.' },
    { section: 'Another run tries at the same time' },
    { from: 'ci2', to: 's3', label: 'create .tflock', caption: 'A second pipeline tries to take the lock while job A holds it.' },
    { from: 's3', to: 'ci2', label: '412: lock exists', reply: true, caption: 'The conditional write fails and job B stops with "Error acquiring the state lock". Without the lock both would write state and one set of changes would be lost. CI concurrency groups avoid the contention.' },
    { section: 'Apply the reviewed plan' },
    { from: 'tf', to: 'api', label: 'create / update / delete', caption: 'apply tfplan executes exactly the reviewed plan, in dependency order and in parallel where possible.' },
    { from: 'tf', to: 's3', label: 'PUT new state', caption: 'Terraform writes the new state with an incremented serial. Bucket versioning lets you recover an earlier state if it is ever corrupted.' },
    { from: 'tf', to: 's3', label: 'DELETE .tflock', caption: 'The lock is released. If the job is killed before this, the lock stays: confirm nothing is running, then terraform force-unlock LOCK_ID.' },
    { from: 'ci', to: 'ci', label: 'nightly plan', caption: 'Drift detection: a scheduled plan -detailed-exitcode exits 2 when reality differs from code. Reconcile by applying or by codifying the change; apply -refresh-only updates state without touching infrastructure.' },
  ],
});

registerDiagram({
  id: 'cloud-ci-oidc-federation',
  roadmap: 'cloud', module: 9, topic: 'CI/CD: Keyless OIDC, Immutable Artefacts and Environment Promotion',
  kind: 'sequence',
  title: 'Keyless CI: GitHub Actions OIDC to AWS and Azure',
  desc: 'The CI job proves who it is with a short-lived signed token describing the repo, branch and environment. The cloud trusts that issuer and exchanges the token for temporary credentials, so no secret lives in CI.',
  actors: [
    { id: 'gh', label: 'GitHub OIDC', sub: 'token issuer', color: 'gray', info: 'Issuer https://token.actions.githubusercontent.com. It signs a JWT per job, with claims such as sub, aud, repository, ref, environment and job_workflow_ref.' },
    { id: 'job', label: 'Actions job', sub: 'deploy-prod', icon: '🤖', color: 'blue', info: 'Needs permissions: id-token: write. aws-actions/configure-aws-credentials or azure/login (client ID, tenant ID, subscription ID, no secret) do the exchange.' },
    { id: 'sts', label: 'AWS STS / Entra ID', sub: 'trusts the issuer', color: 'purple', info: 'AWS: an IAM OIDC identity provider plus a role whose trust policy conditions on aud and sub. Azure: a federated identity credential (issuer + subject) on an app registration or user-assigned managed identity.' },
    { id: 'api', label: 'Cloud APIs', sub: 'prod account', color: 'green' },
  ],
  steps: [
    { section: 'Gate and token' },
    { from: 'job', to: 'job', label: 'env: prod approved', caption: 'The job targets the GitHub environment prod, which requires a reviewer approval and allows only the main branch. Only then does it run.' },
    { from: 'job', to: 'gh', label: 'request ID token', caption: 'The job asks the GitHub OIDC provider for a token with the audience the cloud expects (sts.amazonaws.com, or api://AzureADTokenExchange).' },
    { from: 'gh', to: 'job', label: 'JWT: sub, aud, repo', reply: true, caption: 'The signed JWT says sub = repo:acme/payments:environment:prod and lives for minutes. It is useless to anyone who cannot get the cloud to trust it.' },
    { section: 'AWS exchange' },
    { from: 'job', to: 'sts', label: 'JWT + role ARN', caption: 'The job calls sts:AssumeRoleWithWebIdentity and sends the JWT and the role ARN to STS. No access key is involved at any point.' },
    { from: 'sts', to: 'gh', label: 'fetch JWKS (cached)', caption: 'STS verifies the signature with the issuer public keys, which it fetches through the registered IAM OIDC provider.' },
    { from: 'sts', to: 'sts', label: 'check aud + sub', caption: 'The trust policy requires aud = sts.amazonaws.com and sub = repo:acme/payments:environment:prod exactly. A wildcard like repo:acme/* would let any repo or branch in the org deploy to prod.' },
    { from: 'sts', to: 'job', label: 'temp creds (1 h)', reply: true, caption: 'Temporary credentials for the prod apply role are returned. Use separate roles: a read-only plan role for pull requests and an apply role only for the protected environment.' },
    { from: 'job', to: 'api', label: 'terraform apply / deploy image@digest', caption: 'The job deploys the same signed artefact that passed staging, referenced by digest rather than a tag, so what was tested is what runs.' },
    { section: 'Azure exchange (same idea)' },
    { from: 'job', to: 'sts', label: 'client_assertion=JWT', caption: 'azure/login sends the GitHub JWT to the Entra ID token endpoint as a client assertion. Entra matches issuer, subject and audience against the federated credential.' },
    { from: 'sts', to: 'job', label: 'access token', reply: true, caption: 'An Entra access token is returned and Azure RBAC on the subscription decides what the deployment may change. Azure DevOps service connections use the same workload identity federation.' },
  ],
});

